<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue';
import {useApplication} from '../../application';
import {useRecordingTranscription} from './useRecordingTranscription';
const props=withDefaults(defineProps<{meetingId:string;sessionId?:string|null;canMutate:boolean;autoStart?:boolean}>(),{sessionId:null,autoStart:false});
const emit=defineEmits<{accepted:[]}>(),app=useApplication(),mounted=ref(false),localError=ref<string|null>(null);let autoAttempted=false;
const actor=()=>app.session.current.value?.actor.enterpriseId??null;
const c=useRecordingTranscription(app.recordingTranscriptionApi,app.intake,{context:app.journals,actor,meeting:()=>props.meetingId,sessionId:()=>props.sessionId,canMutate:()=>props.canMutate});
const status=computed(()=>{const source=c.view.value;if(!source)return c.loading.value?'正在读取归档状态':'尚未读取录音归档';if(source.transcriptionTaskId)return '录音转写任务：'+({'READY':'等待处理','RUNNING':'正在转写','RECONCILING':'正在核对结果','SUCCEEDED':'转写完成','FAILED':'处理失败，请在进度页核对','CANCELLED':'任务已取消','STALE':'来源版本已变化'}[source.transcriptionState!]??'请查看处理进度');if(source.state==='NOT_RECORDED')return '当前会议尚无录音';if(source.state==='NOT_REQUESTED')return source.archiveAvailable?'录音归档已就绪，可以开始转写':'正在等待录音归档完成';return {'PENDING':'正在准备录音转写来源','LEASED':'正在准备录音转写来源','DELAYED':'准备暂缓，可重新读取或重试','READY':'录音转写来源已就绪','CANCELLED':'来源准备已取消，请重新核对当前权限'}[source.state];});
async function run(action:()=>Promise<unknown>){localError.value=null;try{await action();}catch(cause){localError.value=cause instanceof Error?cause.message:'录音转写暂未完成，请重试。';}}
async function sync(){if(!mounted.value)return;autoAttempted=false;localError.value=null;c.synchronize();await run(c.load);}
const stopScope=watch(()=>[actor(),props.meetingId,props.sessionId,props.canMutate],()=>{void sync();},{flush:'sync'});
const stopAccepted=watch(()=>c.accepted.value?.taskId,id=>{if(id)emit('accepted');},{flush:'sync'});
const stopAuto=watch(()=>[c.view.value,props.autoStart,c.available.value],()=>{if(mounted.value&&props.autoStart&&!autoAttempted&&props.canMutate&&c.available.value&&c.view.value?.archiveAvailable&&!c.view.value.transcriptionTaskId&&!c.pending.value&&!c.accepted.value){autoAttempted=true;void run(c.start);}},{flush:'post'});
onMounted(async()=>{mounted.value=true;await sync();});onUnmounted(()=>{mounted.value=false;stopScope();stopAccepted();stopAuto();c.dispose();});
async function discard(){try{c.discardRejected();await c.load();}catch(cause){localError.value=cause instanceof Error?cause.message:'原请求暂未核对。';}}
function beforeLeave(){if(c.pending.value&&c.command.state.value!=='ACKNOWLEDGED'){localError.value='转写受理结果尚未确认，请先恢复原请求，或处理明确拒绝的请求。';return false;}return true;}
defineExpose({beforeLeave});
</script>
<template><section class="card card-p recording-transcription" aria-label="录音归档转写"><div class="between"><h2>录音归档转写</h2><button class="btn sm" type="button" :disabled="c.busy.value" @click="run(c.load)">刷新转写状态</button></div><p class="mt12" role="status">{{status}}</p><p class="small muted mt12">使用已保存的完整录音生成会后转写。实时字幕与会后转写分别保存；转写失败后可在处理进度中恢复。</p><p v-if="localError||c.error.value||app.recordingImportScopeError?.value" class="ac-error mt12" role="alert">{{localError??c.error.value??app.recordingImportScopeError?.value}}</p><div v-if="canMutate" class="flex mt12"><template v-if="c.pending.value"><p class="small muted">原转写受理请求尚待核对。</p><button v-if="['PREPARED','UNCERTAIN','ACKNOWLEDGED'].includes(c.command.state.value)" class="btn primary" :disabled="c.busy.value||!c.available.value" @click="run(c.retry)">恢复原转写请求</button><button v-if="['CONFLICT','REJECTED'].includes(c.command.state.value)" class="btn" :disabled="c.busy.value" @click="discard">核对后重新准备</button></template><button v-else-if="!c.view.value?.transcriptionTaskId&&!c.accepted.value" class="btn primary" :disabled="c.busy.value||!c.available.value||!c.view.value?.archiveAvailable" @click="run(c.start)">{{c.view.value?.state==='READY'?'开始转写':'准备并转写'}}</button></div><RouterLink v-if="c.view.value?.transcriptionTaskId||c.accepted.value" class="btn mt12" :to="'/meeting/'+meetingId+'/processing'">查看转写进度</RouterLink></section></template>
<style scoped>.recording-transcription{margin:16px 0}.recording-transcription .between{gap:12px;flex-wrap:wrap}.recording-transcription h2{font-size:16px;margin:0}.recording-transcription .flex{gap:8px;flex-wrap:wrap}</style>
